        "name": "Latest Package Versions",
        "passed": false,
        "reason": "azure-storage-blob 12.25.1 is outdated (latest stable ~12.30.x). azure-identity 1.11.2 is significantly outdated (latest 1.16.2, 5 minor versions behind)."
      },
      {
        "name": "Best Practices",
        "passed": false,
        "reason": "Uses DefaultAzureCredential (good), but has broken Duration classes, no BOM usage, no try-with-resources for clients, and a no-op timeout policy."
