+        return (HttpPipelineCallContext context, HttpPipelineNextPolicy next) -> {
+            context.getData("requestTimeout").ifPresent(timeout -> 
+                context.setHttpRequest(context.getHttpRequest()));
+            return next.process();
+        };
+    }
